static
void kernel_jacobi_1d[[gnu::flatten, gnu::noinline]](int tsteps,
			    int n,
			    DATA_TYPE POLYBENCH_1D(A,N,n),
			    DATA_TYPE POLYBENCH_1D(B,N,n))
{
  int t, i, I;

  /* Create local restrict-qualified views to help the compiler with
     alias analysis and vectorization. A and B never alias in this code. */
  DATA_TYPE *restrict A_ = A;
  DATA_TYPE *restrict B_ = B;

  /* Hoist loop-invariant constants and bounds.
     Use a double literal for the coefficient to preserve the original
     floating-point semantics even when DATA_TYPE is float. */
  const double c      = 0.33333;
  const int    N_     = _PB_N;
  const int    TSTEPS_= _PB_TSTEPS;

  /* Spatial tile size: chosen to keep a tile in L1/L2 while giving each
     thread a reasonably large chunk of contiguous work. */
  const int I_TILE = 4096;

#pragma scop
  /* Parallelize the spatial dimension while keeping the time-stepping
     dimension sequential. A single parallel region amortizes thread
     startup/teardown overhead over all time steps. */
#pragma omp parallel private(t, i, I)
  {
    for (t = 0; t < TSTEPS_; t++)
    {
      /* --- Sweep 1: update B from A (Jacobi step on A) --- */
#pragma omp for schedule(static)
      for (I = 1; I < N_ - 1; I += I_TILE)
      {
        int i_end = I + I_TILE;
        if (i_end > N_ - 1)
          i_end = N_ - 1;

        /* Inner loop: contiguous, no loop-carried dependences.
           Mark it SIMD-friendly so the compiler can generate vector code. */
#pragma omp simd
        for (i = I; i < i_end; i++)
        {
          B_[i] = (DATA_TYPE)(c * (A_[i-1] + A_[i] + A_[i+1]));
        }
      }

      /* Implicit barrier here (end of omp for) ensures all B_[i] for this
         time step are computed before starting the second sweep. */

      /* --- Sweep 2: update A from B (Jacobi step on B) --- */
#pragma omp for schedule(static)
      for (I = 1; I < N_ - 1; I += I_TILE)
      {
        int i_end = I + I_TILE;
        if (i_end > N_ - 1)
          i_end = N_ - 1;

#pragma omp simd
        for (i = I; i < i_end; i++)
        {
          A_[i] = (DATA_TYPE)(c * (B_[i-1] + B_[i] + B_[i+1]));
        }
      }
      /* Second implicit barrier here ensures all A_[i] for this time step
         are complete before any thread proceeds to t+1. */
    }
  }
#pragma endscop

}


