                                                    int n,
                                                    DATA_TYPE POLYBENCH_1D(A,N,n),
                                                    DATA_TYPE POLYBENCH_1D(B,N,n))
{
  /* Hoist the Jacobi coefficient out of the loops so the compiler can
     keep it in a register instead of reloading it every iteration. */
  const DATA_TYPE coeff = (DATA_TYPE)0.33333;

  /* Use restrict-qualified local pointers: A and B are separate
     allocations in PolyBench, so this is semantically valid and
     helps the compiler vectorize aggressively. */
  DATA_TYPE * restrict a = A;
  DATA_TYPE * restrict b = B;

  /* Last index of the interior region (loop upper bound is exclusive). */
  const int i_end = _PB_N - 1;

