      for (int i = 1; i < i_end; ++i)
        b[i] = coeff * (a[i-1] + a[i] + a[i+1]);

      /* Implicit barrier here (end of omp for) ensures all B[i] at
         time t are available before starting the A update. */

      /* Sweep 2: update A from B.
         Again, iterations in i are independent (read-only 'b',
         disjoint writes to 'a'), so we parallelize and SIMD-vectorize. */
#pragma omp for simd schedule(static)
      for (int i = 1; i < i_end; ++i)
        a[i] = coeff * (b[i-1] + b[i] + b[i+1]);

      /* Implicit barrier here ensures all A[i] at time t+1 are written
         before any thread advances its local t to t+1 in the loop. */
    }
  }
