/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Optimizations applied:

   - The time loop (t) remains strictly sequential: Jacobi depends on
     the previous time step.

   - The spatial loop (i) is parallelized (when OpenMP is enabled)
     because each update uses only the "other" array (A for B-update,
     B for A-update), making iterations over i independent.

   - OpenMP 'for simd' is used to express both thread-level and
     SIMD-level parallelism over i. When compiled without OpenMP
     support, these pragmas are removed at preprocessing time and the
     code falls back to the plain, optimized sequential loops.

   - Loop-invariant stencil coefficient is hoisted into a local
     const scalar so the compiler can keep it in a register.

   - Local restrict-qualified pointers are introduced to help the
     compiler with alias analysis and vectorization, while preserving
     the original array semantics.
*/
static
void kernel_jacobi_1d[[gnu::flatten, gnu::noinline]](int tsteps,
			    int n,
			    DATA_TYPE POLYBENCH_1D(A,N,n),
			    DATA_TYPE POLYBENCH_1D(B,N,n))
{
  /* Hoist the stencil constant; identical value as in the original code. */
  const DATA_TYPE c = (DATA_TYPE)0.33333;

  /* Local restrict pointers to improve alias analysis and enable better
     vectorization and scheduling. A and B are distinct PolyBench arrays,
     so this is semantically correct. */
  DATA_TYPE * restrict a = A;
  DATA_TYPE * restrict b = B;

  /* Cache the interior loop bounds once; the compiler would do this
     anyway, but writing it explicitly makes the intent clear. */
  const int i_start = 1;
  const int i_end   = _PB_N - 1; /* loop condition: i < i_end => i = 1..N-2 */

#pragma scop
#ifdef _OPENMP

  /* Single parallel region for all time steps to avoid repeated
     fork/join overhead. Within each time step, two work-sharing
     loops are used: one for updating B from A, then one for updating
     A from B. The implicit barrier at the end of each 'for' ensures
     that all B[i] at time t are computed before any A[i] at time t
     is updated, preserving the original execution order across
     sweeps and time steps. */
  #pragma omp parallel
  {
    int t;
    int i;

    for (t = 0; t < _PB_TSTEPS; ++t)
      {
        /* Sweep 1: B := Jacobi(A)
           Each iteration writes to a distinct b[i] and reads from a[],
           so iterations over i are independent and can be distributed
           across threads and SIMD lanes. */
        #pragma omp for simd schedule(static)
        for (i = i_start; i < i_end; ++i)
          {
            b[i] = c * (a[i-1] + a[i] + a[i+1]);
          }

        /* Implicit barrier here: all threads have finished B-update for
           time step t before proceeding to update A. */

        /* Sweep 2: A := Jacobi(B)
           Same independence pattern: disjoint writes to a[i], read-only
           access to b[]. */
        #pragma omp for simd schedule(static)
        for (i = i_start; i < i_end; ++i)
          {
            a[i] = c * (b[i-1] + b[i] + b[i+1]);
          }

        /* Implicit barrier here: guarantees that all A[i] at time t
           are complete before any thread advances to time t+1, which
           is required since B at t+1 depends on A at t. */
      }
  }

#else  /* !_OPENMP: purely sequential, but still optimized and vectorizable */

  int t, i;

  for (t = 0; t < _PB_TSTEPS; ++t)
    {
      /* Sweep 1: B := Jacobi(A) */
      for (i = i_start; i < i_end; ++i)
        {
          b[i] = c * (a[i-1] + a[i] + a[i+1]);
        }

      /* Sweep 2: A := Jacobi(B) */
      for (i = i_start; i < i_end; ++i)
        {
          a[i] = c * (b[i-1] + b[i] + b[i+1]);
        }
    }

#endif /* _OPENMP */
#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int tsteps = TSTEPS;

  /* Variable declaration/allocation. */
  POLYBENCH_1D_ARRAY_DECL(A, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(B, DATA_TYPE, N, n);


  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(B));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_jacobi_1d(tsteps, n, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(B));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(A)));

