			    DATA_TYPE POLYBENCH_1D(A,N,n),
			    DATA_TYPE POLYBENCH_1D(B,N,n))
{
  /* Hoist the stencil coefficient into a local constant so the compiler
     can keep it in a register across all iterations. This literal value
     matches the original code exactly. */
  const DATA_TYPE c = (DATA_TYPE)0.33333;

  /* Create local restrict-qualified pointers to help the compiler
     assume that A and B do not alias, which improves vectorization. */
  DATA_TYPE *restrict A1 = A;
  DATA_TYPE *restrict B1 = B;

#pragma scop
  /* Parallelize over the spatial dimension for each time step.
     - The outer t-loop remains sequential (per Jacobi dependencies).
     - For a fixed t:
         * B1[i] depends only on A1[.] at time t  -> parallel in i.
         * A1[i] depends only on B1[.] at time t  -> parallel in i.
     A single OpenMP parallel region avoids repeated fork/join overhead.
     When compiled without -fopenmp, all OpenMP pragmas are ignored and
     the code executes the same sequential algorithm as the original. */
#pragma omp parallel
  {
    for (int t = 0; t < _PB_TSTEPS; t++)
      {
        /* Sweep 1: update B from A.
           Each iteration writes a distinct B1[i] and reads only from A1. */
#pragma omp for simd schedule(static)
        for (int i = 1; i < _PB_N - 1; i++)
          {
            B1[i] = c * (A1[i-1] + A1[i] + A1[i+1]);
          }

        /* Sweep 2: update A from B.
           The implicit barrier at the end of the previous 'omp for'
           guarantees that all B1[i] are available before this loop. */
#pragma omp for simd schedule(static)
        for (int i = 1; i < _PB_N - 1; i++)
          {
            A1[i] = c * (B1[i-1] + B1[i] + B1[i+1]);
          }
        /* Implicit barrier here ensures completion of A-update for
           time step t before any thread advances to t+1. */
      }
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int tsteps = TSTEPS;

  /* Variable declaration/allocation. */
  POLYBENCH_1D_ARRAY_DECL(A, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(B, DATA_TYPE, N, n);


  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(B));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_jacobi_1d(tsteps, n, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(B));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(A)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);

  return 0;
}
